            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1 and color != background:
                singles.append(cells[0])

    out = [row[:] for row in grid]
    for r, c in singles:
        votes = Counter()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                votes[grid[nr][nc]] += 1
        if votes:
            best = max(votes.values())
            tied = [color for color, n in votes.items() if n == best]
            if background in tied and len(tied) > 1:
                tied.remove(background)
            out[r][c] = max(tied, key=lambda color: counts[color])

    return out
